// 국적·영주 모의 평가 — 추가 문제(q061~q400) 아랍어 (질문 · 설명) ⚠️ 초안: 원어민 검수 필요
export const MOCK_AR_MORE: Record<string, { q: string; explain: string }> = {
  q061: { q: 'إلامَ يرمز شكل «تايغوك» (태극) في وسط علم تايغوكغي؟', explain: 'يرمز شكل «تايغوك» إلى التناغم بين الين (الأزرق) واليانغ (الأحمر) (음과 양의 조화).' },
  q062: { q: 'أيّ الرموز الأربعة (4괘) في علم تايغوكغي يدلّ على السماء؟', explain: 'الرمز الدالّ على السماء هو «غون» (건괘)، أما 곤괘 فيدلّ على الأرض، و감괘 على الماء، و리괘 على النار.' },
  q063: { q: 'على ماذا يدلّ رمز «ري» (리괘) من الرموز الأربعة في علم تايغوكغي؟', explain: 'يدلّ رمز «ري» (리괘) على النار (불).' },
  q064: { q: 'إلامَ ترمز الخلفية البيضاء لعلم تايغوكغي؟ اختر الإجابة الصحيحة.', explain: 'ترمز الخلفية البيضاء إلى الإشراق والنقاء وحبّ السلام (밝음과 순수, 평화를 사랑하는 마음).' },
  q065: { q: 'في أيّ يوم من الأيام التالية يُرفع علم تايغوكغي منخفضًا بمقدار عرضه (تنكيس العلم)؟', explain: 'في يوم الذكرى الوطني (현충일)، الذي يُكرَّم فيه من ضحّوا بحياتهم من أجل الوطن، يُنكَّس العلم.' },
  q066: { q: 'متى يوافق «هيونتشونغ إيل» (현충일)، يوم تكريم من ضحّوا بحياتهم من أجل الوطن؟', explain: 'يوافق «هيونتشونغ إيل» السادس من يونيو (6월 6일)، وهو يوم عطلة رسمية.' },
  q067: { q: 'أيّ ممّا يلي ليس من الأعياد الوطنية (국경일)؟', explain: 'الأعياد الوطنية الخمسة هي 삼일절 و제헌절 و광복절 و개천절 و한글날، أما يوم الطفل (어린이날) فهو عطلة رسمية لكنه ليس عيدًا وطنيًا.' },
  q068: { q: 'كم عدد الأعياد الوطنية (국경일) في كوريا؟', explain: 'عدد الأعياد الوطنية خمسة (5개): 삼일절 و제헌절 و광복절 و개천절 و한글날.' },
  q069: { q: 'في أيّ يوم وشهر يوافق «غيتشونجول» (개천절)؟', explain: 'يوافق «غيتشونجول»، ذكرى تأسيس مملكة «غوجوسون» (고조선)، الثالث من أكتوبر (10월 3일).' },
  q070: { q: 'ما العيد الوطني الذي يُحيي ذكرى حركة الاستقلال التي وقعت عام 1919؟', explain: 'يوم الأول من مارس (삼일절) هو ذكرى حركة الأول من مارس عام 1919.' },
  q071: { q: 'في أيّ يوم وشهر يوافق «غوانغبوكجول» (광복절)؟', explain: 'يوافق «غوانغبوكجول»، ذكرى استعادة البلاد استقلالها، الخامس عشر من أغسطس (8월 15일).' },
  q072: { q: 'بماذا يُحتفى في «يوم الهانغول» (한글날)؟', explain: 'يُحيي «يوم الهانغول» ذكرى ابتكار الملك سيجونغ أبجدية «هونمين جونغئوم» ونشرها بين الناس (훈민정음을 만들어 널리 알린 것).' },
  q073: { q: 'ما اسم الختم الذي يرمز إلى الدولة ويُختم به على الوثائق الرسمية المهمة؟', explain: 'الختم الذي يرمز إلى الدولة هو «الختم الوطني» (국새)، ويُستخدم على الوثائق الرسمية المهمة.' },
  q074: { q: 'ما الطائر الأسطوري المنحوت على مقبض الختم الوطني (국새) المستخدم حاليًا؟', explain: 'نُحت على مقبض الختم الوطني الحالي طائر العنقاء الأسطوري (봉황).' },
  q075: { q: 'ما الرسم الموجود في وسط شعار الدولة (국장) لجمهورية كوريا؟', explain: 'يتوسّط شعارَ الدولة رمزُ «تايغوك» (태극 문양) داخل بتلات زهرة موغونغهوا، وعلى الشريط كُتبت كلمة «대한민국».' },
  q076: { q: 'ما معنى اسم «موغونغهوا» (무궁화)؟', explain: 'يعني اسم «موغونغهوا» «الزهرة التي تتفتّح مرةً بعد مرة بلا نهاية» (끝없이 피고 또 피는 꽃).' },
  q077: { q: 'متى تتفتّح زهرة موغونغهوا؟ اختر الإجابة الصحيحة.', explain: 'تتفتّح زهرة موغونغهوا مدةً طويلة من الصيف حتى الخريف، أي من يوليو إلى أكتوبر (7월부터 10월까지).' },
  q078: { q: 'كم مقطعًا في النشيد الوطني «أيغوكغا» (애국가)؟', explain: 'يتكوّن «أيغوكغا» من أربعة مقاطع (4절)، ولكل مقطع اللازمة نفسها.' },
  q079: { q: 'ما الكلمة المناسبة للفراغ في لازمة النشيد «أيغوكغا»: «무궁화 삼천리 ( ) 강산»؟', explain: 'تبدأ اللازمة بعبارة «무궁화 삼천리 화려 강산»، أي «أرض الثلاثة آلاف لي البهيّة (화려) بزهور موغونغهوا».' },
  q080: { q: 'مَن لحّن النشيد الوطني «أيغوكغا» الذي يُغنّى اليوم؟', explain: 'لحّن النشيدَ الحالي المؤلّفُ الموسيقي «آن إيك-تاي» (안익태).' },
  q081: { q: 'ما الشجرة المذكورة في المقطع الثاني من «أيغوكغا»: «남산 위에 저 ( )»؟', explain: 'المقطع الثاني هو «남산 위에 저 소나무…»، ومعناه «شجرة الصنوبر (소나무) فوق جبل نامسان كأنها ترتدي درعًا من حديد».' },
  q082: { q: 'عند تحية العلم بالملابس العادية، أين توضع اليد اليمنى؟', explain: 'عند تحية العلم، تُبسط اليد اليمنى وتوضع على الجهة اليسرى من الصدر (왼쪽 가슴) مع النظر إلى العلم.' },
  q083: { q: 'ما الكلمة المناسبة للفراغ في قَسَم الولاء للعلم: «( )롭고 정의로운 대한민국»؟', explain: 'يرد في القسم عبارة «자유롭고 정의로운 대한민국»، أي «جمهورية كوريا الحرّة (자유) والعادلة».' },
  q084: { q: 'ما أول ما يُؤدّى في المراسم الوطنية (국민의례) في الفعاليات الرسمية؟', explain: 'تُؤدّى المراسم الوطنية بالترتيب: تحية العلم (국기에 대한 경례)، ثم إنشاد النشيد الوطني، ثم الوقوف دقيقة صمت.' },
  q085: { q: 'ما معنى اسم «هونمين جونغئوم» (훈민정음)؟', explain: 'يعني «هونمين جونغئوم» «الأصوات الصحيحة لتعليم الشعب» (백성을 가르치는 바른 소리).' },
  q086: { q: 'في أيّ عام أعلن الملك سيجونغ أبجدية «هونمين جونغئوم» ونشرها بين الشعب؟', explain: 'ابتُكرت «هونمين جونغئوم» عام 1443 وأُعلنت عام 1446 (1446년).' },
  q087: { q: 'ما الكتاب الذي يشرح مبادئ ابتكار الهانغول وطريقة استخدامه؟', explain: 'كتاب «هونمين جونغئوم هيريبون» (훈민정음 해례본) يشرح مبادئ الهانغول، وأُدرج في سجلّ ذاكرة العالم لليونسكو عام 1997.' },
  q088: { q: 'على شكل ماذا صُمّمت الحروف الساكنة الأساسية في الهانغول (ㄱ، ㄴ، ㅁ، ㅅ، ㅇ)؟', explain: 'صُمّمت الحروف الساكنة الأساسية على شكل الفم واللسان والحلق عند النطق (소리 낼 때의 입과 혀의 모양).' },
  q089: { q: 'على صورة ماذا صُمّمت الحروف المتحركة الأساسية في الهانغول «·، ㅡ، ㅣ»؟', explain: 'صُمّمت الحروف المتحركة الأساسية على صورة السماء (·) والأرض (ㅡ) والإنسان (ㅣ) (하늘·땅·사람).' },
  q090: { q: 'كم كان عدد حروف «هونمين جونغئوم» عند ابتكارها أول مرة؟', explain: 'كانت في البداية 17 حرفًا ساكنًا و11 حرفًا متحركًا، أي 28 حرفًا (28자)، ويُستخدم اليوم 24 حرفًا.' },
  q091: { q: 'أيّ ممّا يلي ليس من الرموز الوطنية لجمهورية كوريا؟', explain: 'الرموز الوطنية لكوريا هي 태극기 و애국가 و무궁화 و국새 و국장، أما زهرة الكرز (벚꽃) فليست منها.' },
  q092: { q: 'من أيّ نوع من أنواع الكتابة الهانغول؟', explain: 'الهانغول كتابة صوتية تُدوِّن أصوات الكلام (소리를 적는 글자).' },
  q093: { q: 'وفقًا للدستور، لمن تعود السيادة في جمهورية كوريا؟', explain: 'تنصّ المادة 1 من الدستور على أن السيادة للشعب (국민) وأن جميع السلطات تنبع منه.' },
  q094: { q: 'عند تعديل الدستور، ما الإجراء الذي يجب المرور به بعد موافقة الجمعية الوطنية؟', explain: 'بعد موافقة الجمعية الوطنية على مشروع تعديل الدستور، يجب أن يحظى بالتأييد في استفتاء شعبي (국민 투표) ليصبح نافذًا.' },
  q095: { q: 'ما النظام السياسي الذي يكون فيه الشعب سيّد البلاد ويقرّر شؤونها؟', explain: 'النظام الذي يكون فيه الشعب سيّد البلاد ويحكمها يُسمّى الديمقراطية (민주주의).' },
  q096: { q: 'ما النظام الذي ينتخب فيه الشعب ممثّلين يتولّون شؤون البلاد نيابةً عنه؟', explain: 'النظام الذي يُنتخب فيه ممثّلون تُوكَل إليهم شؤون البلاد يُسمّى الديمقراطية التمثيلية (대의 민주 정치).' },
  q097: { q: 'عند اختلاف الآراء، ما اسم طريقة اتخاذ القرار وفق الرأي الذي يؤيّده عدد أكبر من الناس؟', explain: 'اتّباع رأي الأغلبية يُسمّى مبدأ الأغلبية (다수결의 원칙)، مع وجوب احترام رأي الأقلية أيضًا.' },
  q098: { q: 'ما المبدأ الذي يقضي بأن تحكم الدولة البلاد وفقًا للقوانين التي يضعها الشعب؟', explain: 'مبدأ حكم البلاد وفقًا للقانون يُسمّى سيادة القانون (법치주의).' },
  q099: { q: 'مَن هو الرئيس الأعلى للسلطة التنفيذية والذي يمثّل البلاد أمام الدول الأخرى؟', explain: 'الرئيس (대통령) هو رأس السلطة التنفيذية ويمثّل الدولة أمام الدول الأخرى.' },
  q100: { q: 'في كوريا، كم مرة يجوز لشخص واحد أن يتولّى الرئاسة؟ اختر الإجابة الصحيحة.', explain: 'مدة الرئاسة ولاية واحدة من 5 سنوات، فلا يجوز تولّيها إلا مرة واحدة (한 번만).' },
  q101: { q: 'كم يجب أن يكون عمر المرشّح للانتخابات الرئاسية على الأقل؟', explain: 'يجب أن يكون المرشّح للرئاسة قد بلغ 40 عامًا (만 40세) على الأقل في يوم الانتخابات.' },
  q102: { q: 'كيف يُنتخب رئيس كوريا؟', explain: 'يُنتخب الرئيس بتصويت مباشر من الشعب (국민이 직접 투표로 뽑는다).' },
  q103: { q: 'إذا تعذّر على الرئيس أداء مهامه لسببٍ ما، فمَن يتولّى صلاحياته بالنيابة أولًا؟', explain: 'إذا تعذّر على الرئيس أداء مهامه، يتولّى رئيس الوزراء (국무총리) صلاحياته بالنيابة أولًا.' },
  q104: { q: 'وفقًا للدستور، مَن يتولّى القيادة العليا للقوات المسلحة؟', explain: 'وفقًا للدستور، الرئيس (대통령) هو القائد الأعلى للقوات المسلحة.' },
  q105: { q: 'ما اسم صلاحية الرئيس في الاعتراض على مشروع قانون أقرّته الجمعية الوطنية وطلب إعادة التصويت عليه؟', explain: 'يمكن للرئيس استخدام حق النقض على مشاريع القوانين (법률안 거부권) لمطالبة الجمعية الوطنية بإعادة التصويت.' },
  q106: { q: 'كم سنة مدة ولاية عضو الجمعية الوطنية؟', explain: 'مدة ولاية عضو الجمعية الوطنية 4 سنوات (4년)، ويجوز له الترشّح مجددًا.' },
  q107: { q: 'ما اسم أعضاء الجمعية الوطنية الذين يُختارون وفق نسبة الأصوات التي يحصل عليها كل حزب؟', explain: 'الأعضاء الذين تُوزَّع مقاعدهم وفق نسبة أصوات الأحزاب يُسمّون نواب التمثيل النسبي (비례대표 국회의원).' },
  q108: { q: 'ما الجهة التي تناقش مشروع الميزانية العامة للعام التالي الذي تعدّه الحكومة وتُقرّه؟', explain: 'عندما تقدّم الحكومة مشروع الميزانية، تناقشه الجمعية الوطنية (국회) وتُقرّه.' },
  q109: { q: 'ماذا يُسمّى قيام الجمعية الوطنية كل عام بفحص ما إذا كانت الجهات الحكومية تؤدّي عملها كما ينبغي؟', explain: 'تراقب الجمعية الوطنية عمل الحكومة من خلال التدقيق في شؤون الدولة (국정 감사).' },
  q110: { q: 'مَن يمثّل الجمعية الوطنية ويدير جلساتها؟', explain: 'رئيس الجمعية الوطنية (국회의장) يمثّلها ويدير جلساتها.' },
  q111: { q: 'بعد أن تصوّت الجمعية الوطنية على توجيه اتهام لعزل الرئيس، ما الجهة التي تقرّر نهائيًا عزله أو عدمه؟', explain: 'المحكمة الدستورية (헌법재판소) هي التي تنظر في عزل الرئيس وتصدر القرار النهائي.' },
  q112: { q: 'عندما يعيّن الرئيس رئيسَ الوزراء، ما الجهة التي يجب أن يحصل على موافقتها؟', explain: 'يعيّن الرئيسُ رئيسَ الوزراء بعد الحصول على موافقة الجمعية الوطنية (국회).' },
  q113: { q: 'مَن يساعد الرئيس ويشرف على الوزارات بتوجيه منه؟', explain: 'رئيس الوزراء (국무총리) يساعد الرئيس ويشرف على الوزارات بتوجيه منه.' },
  q114: { q: 'مَن يرأس مجلس الدولة (국무회의) الذي يناقش السياسات الحكومية المهمة؟', explain: 'يرأس مجلسَ الدولة الرئيسُ (대통령)، ونائبه رئيسُ الوزراء.' },
  q115: { q: 'ما الجهة الحكومية المركزية التي تدير برنامج الاندماج الاجتماعي (KIIP) للمهاجرين؟', explain: 'تدير برنامجَ الاندماج الاجتماعي وزارةُ العدل (법무부) المسؤولة عن شؤون الهجرة والدخول والخروج.' },
  q116: { q: 'ما الجهة التي تدقّق في إيرادات الدولة ونفقاتها وتراقب حُسن أداء الموظفين الحكوميين لعملهم؟', explain: 'هيئة الرقابة والتدقيق (감사원) تدقّق في حسابات الدولة وتراقب أداء الموظفين الحكوميين.' },
  q117: { q: 'ما أعلى محكمة في كوريا؟', explain: 'المحكمة العليا (대법원) هي أعلى محكمة، وتتولّى في الغالب درجة التقاضي الثالثة.' },
  q118: { q: 'ما الجهة التي تحكم بما إذا كان القانون الذي أصدرته الجمعية الوطنية مخالفًا للدستور؟', explain: 'المحكمة الدستورية (헌법재판소) هي التي تحكم في مدى توافق القوانين مع الدستور.' },
  q119: { q: 'كم عدد قضاة المحكمة الدستورية؟', explain: 'تتألّف المحكمة الدستورية من 9 قضاة (9명).' },
  q120: { q: 'ما المحكمة التي تنظر أساسًا في قضايا الطلاق ومشكلات العلاقات الأسرية؟', explain: 'تنظر محكمة الأسرة (가정 법원) أساسًا في قضايا الأسرة مثل الطلاق والولاية على الأبناء.' },
  q121: { q: 'ما مبدأ الانتخاب الذي يكون فيه لكل شخص صوت واحد، ولجميع الأصوات القيمة نفسها؟', explain: 'أن يكون لكل شخص صوت واحد بالقيمة نفسها هو مبدأ الاقتراع المتساوي (평등 선거).' },
  q122: { q: 'ما مبدأ الانتخاب الذي يحقّ فيه لكل من بلغ سنًّا معيّنة أن يصوّت بغضّ النظر عن الثروة أو الجنس أو المستوى التعليمي؟', explain: 'منح حق التصويت لجميع المواطنين الذين بلغوا السنّ المحددة هو مبدأ الاقتراع العام (보통 선거).' },
  q123: { q: 'أيّ ممّا يلي ليس من المبادئ الأربعة للانتخابات الديمقراطية؟', explain: 'المبادئ الأربعة هي 보통·평등·직접·비밀 선거، أما الانتخاب العلني (공개 선거) فليس منها لأن التصويت يجب أن يكون سرّيًا.' },
  q124: { q: 'ما الهيئة التي أُنشئت بموجب الدستور لإدارة الانتخابات والاستفتاءات بنزاهة؟', explain: 'لجنة إدارة الانتخابات (선거관리위원회) هيئة دستورية تدير الانتخابات والاستفتاءات بنزاهة.' },
  q125: { q: 'ما اسم النظام الذي يتيح لمن يصعب عليه التصويت يوم الانتخابات أن يصوّت مبكرًا قبل ذلك اليوم؟', explain: 'التصويت المبكر (사전 투표) نظام يُتيح التصويت قبل يوم الانتخابات خلال يومين محدّدين.' },
  q126: { q: 'ما الذي يجب إحضاره عند الذهاب إلى مركز الاقتراع للتصويت؟', explain: 'في مركز الاقتراع، يُتحقَّق من الهوية ببطاقة الهوية (신분증) ثم يُسلَّم الناخب ورقة الاقتراع.' },
  q127: { q: 'ما طبيعة يوم الانتخابات الرئاسية أو انتخابات الجمعية الوطنية؟', explain: 'يوم الانتخابات الرئاسية والتشريعية عطلة رسمية (공휴일) ليتمكّن الجميع من التصويت.' },
  q128: { q: 'كل كم سنة تُجرى الانتخابات المحلية لاختيار رؤساء البلديات وحكّام المقاطعات وأعضاء المجالس المحلية؟', explain: 'تُجرى الانتخابات المحلية في وقت واحد في جميع أنحاء البلاد كل 4 سنوات (4년).' },
  q129: { q: 'في أيّ انتخابات يحقّ للأجنبي البالغ 18 عامًا فأكثر، والذي مضت 3 سنوات على حصوله على الإقامة الدائمة، أن يصوّت؟', explain: 'يحقّ للأجنبي الذي مضت 3 سنوات على حصوله على الإقامة الدائمة أن يصوّت في الانتخابات المحلية (지방 선거) في منطقة سكنه.' },
  q130: { q: 'مَن يحقّ له التصويت في الانتخابات الرئاسية؟ اختر الإجابة الصحيحة.', explain: 'لا يصوّت في الانتخابات الرئاسية إلا مواطنو جمهورية كوريا البالغون 18 عامًا فأكثر (만 18세 이상 대한민국 국민)، ومنهم المتجنّسون.' },
  q131: { q: 'ما الحدّ الأدنى لسنّ الترشّح لانتخابات الجمعية الوطنية؟', explain: 'يحقّ للمواطن البالغ 18 عامًا فأكثر (만 18세) الترشّح لانتخابات الجمعية الوطنية.' },
  q132: { q: 'ما اسم التنظيم الذي يؤسّسه أشخاص يتشاركون الأفكار السياسية بهدف الوصول إلى السلطة؟', explain: 'التنظيم الذي يجمع أشخاصًا يتشاركون التوجّه السياسي بهدف الوصول إلى السلطة يُسمّى الحزب السياسي (정당).' },
  q133: { q: 'ما الصحيح بشأن قبول المال أو الهدايا من المرشّحين في فترة الانتخابات؟', explain: 'قبول المال أو الهدايا من المرشّحين مخالف للقانون وقد يُعاقَب عليه (불법이므로 처벌받을 수 있다).' },
  q134: { q: 'ما النظام الذي ينتخب فيه سكان المنطقة ممثّليهم ويديرون شؤون منطقتهم بأنفسهم؟', explain: 'أن يقرّر السكان شؤون منطقتهم ويديروها بأنفسهم يُسمّى نظام الحكم الذاتي المحلي (지방 자치 제도).' },
  q135: { q: 'ما الجهة التي تضع اللوائح المحلية وتناقش ميزانية الإدارة المحلية؟', explain: 'المجلس المحلي (지방 의회) هو المكان الذي يضع فيه الأعضاء المنتخَبون اللوائح ويناقشون الميزانية.' },
  q136: { q: 'ماذا تُسمّى القواعد المحلية التي يضعها المجلس المحلي في حدود القوانين؟', explain: 'القواعد التي يضعها المجلس المحلي تُسمّى اللوائح المحلية (조례).' },
  q137: { q: 'ما لقب رئيس الإدارة المحلية المسؤول عن شؤون المقاطعة الريفية (군) مثل 양평군 و가평군؟', explain: 'رئيس إدارة المقاطعة هو «غونسو» (군수)، وينتخبه السكان.' },
  q138: { q: 'مَن المسؤول عن التعليم في المدينة أو المقاطعة والذي ينتخبه السكان مباشرة؟', explain: 'يُنتخب مدير التعليم في المدينة أو المقاطعة (교육감) مباشرةً من السكان في الانتخابات المحلية.' },
  q139: { q: 'ما النظام الذي يتيح للسكان عزل رئيس الإدارة المحلية أو عضو المجلس المحلي المقصّر عن طريق التصويت؟', explain: 'النظام الذي يعزل فيه السكان رئيس الإدارة المحلية أو عضو المجلس المحلي بالتصويت يُسمّى نظام الاستدعاء الشعبي (주민 소환제).' },
  q140: { q: 'أيّ ممّا يلي يُعدّ من وحدات الحكم المحلي الإقليمية (광역 자치 단체)؟', explain: 'المدن الخاصة والمدن الكبرى والمقاطعات، مثل مدينة سيول الخاصة (서울특별시)، وحدات إقليمية، أما 시·군·구 فوحدات محلية أساسية.' },
  q141: { q: 'ما اسم الحق في المشاركة في الحياة السياسية للبلاد، كالتصويت في الانتخابات أو الترشّح لها؟', explain: 'الحقوق التي تتيح المشاركة السياسية، مثل حق التصويت وحق الترشّح، تُسمّى الحقوق السياسية (참정권).' },
  q142: { q: 'ما اسم الحق في الترشّح للانتخابات والفوز بها ممثّلًا عن الناس؟', explain: 'حق التصويت هو 선거권، أما حق الترشّح والفوز بالانتخاب فهو حق الترشّح (피선거권).' },
  q143: { q: 'أيّ العبارات التالية صحيحة بشأن التصويت في كوريا؟', explain: 'التصويت حقّ للمواطن، فلا غرامة على من لا يصوّت (투표하지 않아도 벌금은 없다)، لكن يُستحسن المشاركة.' },
  q144: { q: 'ما شكل نظام الحكم في كوريا؟', explain: 'كوريا دولة ذات نظام رئاسي (대통령제)، يقود فيه الرئيسُ المنتخب من الشعب السلطةَ التنفيذية.' },
  q145: { q: 'ما الحق الذي يضمن ألا يتعرض أي مواطن للتمييز بسبب الجنس أو الدين أو المكانة الاجتماعية؟', explain: 'حق عدم التمييز أمام القانون هو حق المساواة (평등권).' },
  q146: { q: 'ما الحق الذي يضمن العيش في بيئة نظيفة وصحية؟', explain: 'ينص الدستور على حق كل مواطن في العيش في بيئة صحية ومريحة، ويُسمّى الحق البيئي (환경권).' },
  q147: { q: 'ما الحق الذي يتيح مطالبة الدولة بضمان حياة كريمة لائقة بالإنسان؟', explain: 'حق المطالبة بحياة كريمة كالتعليم والعمل والرعاية الاجتماعية هو الحق الاجتماعي (사회권).' },
  q148: { q: 'إلى أي نوع من الحقوق الأساسية ينتمي حق اعتناق الدين أو عدم اعتناقه بحرية؟', explain: 'حرية الدين من حقوق الحرية (자유권) التي لا يجوز للدولة التدخل فيها.' },
  q149: { q: 'ما الحق الذي يتيح مطالبة الدولة بالمحاكمة وغيرها عند انتهاك الحقوق؟', explain: 'حق مطالبة الدولة بالإنصاف، مثل رفع دعوى أمام المحكمة، هو حق المطالبة (청구권).' },
  q150: { q: 'ما القيمة التي تُعدّ أساس جميع الحقوق الأساسية في الدستور؟', explain: 'تنص المادة 10 من الدستور على أن لكل مواطن كرامة الإنسان وقيمته (인간의 존엄과 가치).' },
  q151: { q: 'إلى ماذا يجب الاستناد عند تقييد الحقوق الأساسية للمواطنين في حالات الضرورة؟', explain: 'لا يجوز تقييد الحقوق الأساسية إلا بقانون (법률) عند الضرورة لحماية الأمن الوطني والنظام العام والمصلحة العامة.' },
  q152: { q: 'إلى أي جهة حكومية يمكن تقديم شكوى عند التعرض للتمييز أو انتهاك حقوق الإنسان؟', explain: 'عند انتهاك حقوق الإنسان أو التعرض للتمييز يمكن تقديم شكوى إلى اللجنة الوطنية لحقوق الإنسان (국가인권위원회).' },
  q153: { q: 'ما الذي يُعدّ في الدستور حقًا للمواطن وواجبًا عليه في الوقت نفسه؟', explain: 'التعليم (교육) حق في التعلّم وواجب في تعليم الأبناء في آن واحد.' },
  q154: { q: 'بسبب أي واجب يلتحق الرجال الكوريون بالجيش عند بلوغهم سنًّا معينة؟', explain: 'أداء الخدمة العسكرية لحماية الوطن هو واجب الدفاع الوطني (국방의 의무).' },
  q155: { q: 'ما الواجب الذي يُلزم الوالدين بإرسال أبنائهم إلى المدرسة الابتدائية والمتوسطة؟', explain: 'ضمان حصول الأبناء على التعليم الإلزامي هو واجب التعليم (교육의 의무).' },
  q156: { q: 'كم سنة مدة التعليم الإلزامي في كوريا؟', explain: 'التعليم الإلزامي 6 سنوات ابتدائية و3 سنوات متوسطة، أي 9 سنوات (9년).' },
  q157: { q: 'ما الواجب الذي يُلزم المواطن القادر على العمل بأن يعمل بجدّ وإخلاص؟', explain: 'ينص الدستور على أن على كل مواطن واجب العمل (근로의 의무).' },
  q158: { q: 'ما واجب المواطن المذكور في الدستور إلى جانب الواجبات الأربعة الأساسية؟', explain: 'ينص الدستور على أن على المواطنين السعي لحماية البيئة (환경 보전의 의무).' },
  q159: { q: 'ما العبارة الصحيحة بشأن ضرائب الأجنبي الذي يحصل على دخل من العمل في كوريا؟', explain: 'الأجنبي الذي له دخل في كوريا يدفع الضرائب لكوريا وفقًا للقانون (한국에 세금을 내야 한다).' },
  q160: { q: 'ماذا يجب أن يُفعل في كوريا ليُعترف بالزواج قانونيًا؟', explain: 'حتى بعد إقامة حفل الزفاف، يجب تسجيل الزواج (혼인 신고) ليصبح الزوجان زوجين قانونيًا.' },
  q161: { q: 'في أي سن يبلغ الشخص سن الرشد وفق القانون المدني الكوري؟', explain: 'في كوريا يبلغ الشخص سن الرشد عند إتمام 19 عامًا (만 19세).' },
  q162: { q: 'في كوريا، خلال أي مدة يجب تسجيل المولود بعد ولادته؟', explain: 'يجب تسجيل المولود خلال شهر واحد (1개월 이내) من تاريخ الولادة.' },
  q163: { q: 'ماذا يُسمّى الطلاق الذي يتم باتفاق الزوجين؟', explain: 'الطلاق الذي يتفق عليه الزوجان ويصادق عليه القضاء هو الطلاق بالتراضي (협의 이혼).' },
  q164: { q: 'عند الميراث وفق القانون دون وصية، كم يأخذ الزوج أو الزوجة مقارنة بنصيب الابن الواحد؟', explain: 'في الميراث القانوني يحصل الزوج أو الزوجة على 1.5 ضعف (1.5배를 받는다) نصيب الابن.' },
  q165: { q: 'ما السجل الرسمي الذي تُدوَّن فيه العلاقات الأسرية كالولادة والزواج والوفاة؟', explain: 'منذ عام 2008 تُسجَّل العلاقات الأسرية في سجل العلاقات الأسرية (가족관계등록부) بدلًا من 호적.' },
  q166: { q: 'ما العبارة الصحيحة عن العنف الأسري؟', explain: 'العنف الأسري جريمة، لذا يمكن الإبلاغ عنه على الرقم 112 وغيره للحصول على الحماية (범죄이므로 신고할 수 있다).' },
  q167: { q: 'أيّ مما يلي ليس من حقوق العمل الثلاثة التي يكفلها الدستور؟', explain: 'حقوق العمل الثلاثة هي حق التنظيم وحق التفاوض الجماعي وحق العمل الجماعي، أما حق الانتخاب (선거권) فليس منها.' },
  q168: { q: 'كم ساعة هي ساعات العمل الأساسية في الأسبوع وفق قانون معايير العمل؟', explain: 'ساعات العمل الأساسية 8 ساعات يوميًا و40 ساعة أسبوعيًا (40시간).' },
  q169: { q: 'ما بدل يوم الراحة المدفوع الذي يُمنح لمن يعمل 15 ساعة أو أكثر أسبوعيًا ويحضر في جميع الأيام المحددة؟', explain: 'عند استيفاء الشروط يحصل العامل على أجر يوم كامل في يوم الراحة، ويسمى بدل الراحة الأسبوعية (주휴 수당).' },
  q170: { q: 'كم يومًا من الإجازة السنوية المدفوعة يحصل عليها العامل الذي حضر 80% أو أكثر من أيام العمل خلال سنة؟', explain: 'إذا حضر العامل 80% أو أكثر خلال سنة يحصل على 15 يومًا (15일) من الإجازة السنوية المدفوعة.' },
  q171: { q: 'إلى أي جهة حكومية يمكن تقديم شكوى عندما لا تدفع الشركة الأجور المستحقة؟', explain: 'يمكن الإبلاغ عن الأجور غير المدفوعة إلى وزارة العمل والتوظيف (고용노동부).' },
  q172: { q: 'ما العبارة الصحيحة بشأن استغلال المنصب أو العلاقات في مكان العمل لإلحاق أذى جسدي أو نفسي بموظف آخر؟', explain: 'التنمّر في مكان العمل محظور بموجب قانون معايير العمل (법으로 금지되어 있다).' },
  q173: { q: 'كم يومًا على الأقل يجب على الشركة إخطار العامل مسبقًا قبل فصله؟', explain: 'يجب الإخطار بالفصل قبل 30 يومًا (30일) أو دفع أجر لا يقل عن 30 يومًا بدلًا من ذلك.' },
  q174: { q: 'كم يومًا مجموع إجازة الأمومة قبل الولادة وبعدها للعاملة التي تلد طفلًا واحدًا؟', explain: 'إجازة الأمومة 90 يومًا (90일)، و120 يومًا في حالة التوائم.' },
  q175: { q: 'عند العمل 8 ساعات في اليوم، ما وقت الاستراحة الذي يضمنه القانون أثناء ساعات العمل؟', explain: 'من يعمل 4 ساعات يستريح 30 دقيقة على الأقل، ومن يعمل 8 ساعات يستريح ساعة على الأقل (1시간 이상).' },
  q176: { q: 'ما العبارة الصحيحة بشأن الحد الأدنى لأجور العمال الأجانب؟', explain: 'يُطبَّق الحد الأدنى للأجور على جميع العمال بالتساوي بغض النظر عن الجنسية (한국인과 똑같이 적용된다).' },
  q177: { q: 'ما رقم هاتف استشارات المستهلك عند التعرض لضرر بعد شراء سلعة أو خدمة؟', explain: 'يمكن الحصول على استشارات أضرار المستهلك من مركز استشارات المستهلك على الرقم 1372.' },
  q178: { q: 'أيّ مما يلي ليس من حقوق المستهلك التي يكفلها القانون الأساسي للمستهلك؟', explain: 'للمستهلك حق السلامة وحق المعرفة وحق التعويض، لكن ليس له حق تحديد الأسعار كما يشاء (물건값을 마음대로 정할 권리).' },
  q179: { q: 'عند شراء سلعة من بائع جاء إلى المنزل، خلال كم يومًا من استلام العقد يمكن إلغاء الشراء؟', explain: 'يمكن إلغاء شراء السلع المشتراة عبر البيع المنزلي خلال 14 يومًا (14일) من تاريخ استلام العقد.' },
  q180: { q: 'أيّ مما يُكتب على عبوة الطعام يدل على آخر يوم يكون فيه تناوله آمنًا؟', explain: 'منذ عام 2023 يُكتب على الأطعمة غالبًا تاريخ انتهاء الاستهلاك (소비기한) الذي يبيّن مدة صلاحية الأكل.' },
  q181: { q: 'ماذا يحدث إذا دخّنت في منطقة يُمنع فيها التدخين؟', explain: 'التدخين في منطقة يُمنع فيها التدخين يستوجب دفع غرامة (과태료를 낸다).' },
  q182: { q: 'في أي المقاعد يجب ربط حزام الأمان عند ركوب السيارة؟', explain: 'منذ عام 2018 أصبح ربط حزام الأمان إلزاميًا في جميع المقاعد (모든 좌석) وعلى جميع الطرق.' },
  q183: { q: 'ما الحد الأساسي للسرعة للسيارات في منطقة حماية الأطفال (منطقة المدارس)؟', explain: 'في منطقة حماية الأطفال يجب عادةً القيادة بسرعة لا تتجاوز 30 كم/ساعة (시속 30km).' },
  q184: { q: 'ما الذي يجب الالتزام به قانونًا عند ركوب السكوتر الكهربائي؟', explain: 'يتطلب ركوب السكوتر الكهربائي رخصة قيادة وارتداء خوذة (면허를 갖고 안전모를 쓴다).' },
  q185: { q: 'ما المدة التي يمكن خلالها القيادة في كوريا برخصة القيادة الدولية الصادرة في الخارج بدءًا من تاريخ الدخول؟', explain: 'تصلح رخصة القيادة الدولية لمدة سنة (1년) من تاريخ الدخول، وبعدها تلزم رخصة كورية.' },
  q186: { q: 'ما العبارة الصحيحة بشأن تدخين القنب (الماريجوانا) في كوريا؟', explain: 'في كوريا تُعدّ المخدرات، بما فيها القنب، غير قانونية ويُعاقب عليها بشدة (불법이며 처벌받는다).' },
  q187: { q: 'ما الجهة التي تقدم استشارات قانونية مجانية ودعمًا في القضايا لمن يصعب عليهم توكيل محامٍ بسبب ظروفهم؟', explain: 'تقدم مؤسسة المساعدة القانونية الكورية (대한법률구조공단، الرقم 132) استشارات مجانية ودعمًا في القضايا.' },
  q188: { q: 'ما نوع المحاكمة التي يُلجأ إليها عند عدم استرداد مال أُقرض لشخص آخر؟', explain: 'تُحلّ النزاعات المالية أو المتعلقة بالممتلكات بين الأفراد عن طريق المحاكمة المدنية (민사 재판).' },
  q189: { q: 'ماذا يجب على الأجنبي أن يفعل إذا أراد البقاء في كوريا بعد انتهاء مدة إقامته؟', explain: 'يجب تقديم طلب تمديد مدة الإقامة إلى مكتب الهجرة قبل انتهائها (만료 전에 연장을 신청한다).' },
  q190: { q: 'إذا انتقل الأجنبي المسجَّل إلى سكن جديد، فخلال كم يومًا من الانتقال يجب الإبلاغ عن تغيير محل الإقامة؟', explain: 'يجب على الأجنبي الذي انتقل أن يبلغ عن تغيير محل إقامته خلال 15 يومًا (15일) من تاريخ الانتقال.' },
  q191: { q: 'ماذا يجب على الأجنبي، كالطالب، أن يفعل إذا أراد ممارسة نشاط خارج نطاق تأشيرته (مثل العمل الجزئي)؟', explain: 'لممارسة نشاط خارج نطاق التأشيرة يجب الحصول على إذن مسبق من مكتب الهجرة (미리 허가를 받는다).' },
  q192: { q: 'ماذا يُسمّى البقاء في كوريا دون مغادرتها بعد انتهاء مدة الإقامة؟', explain: 'تترتب على الإقامة غير القانونية (불법 체류) عقوبات مثل الغرامة والترحيل وحظر الدخول.' },
  q193: { q: 'كم سنة على الأقل يجب الإقامة المتواصلة في كوريا، كمبدأ عام، لتقديم طلب التجنس العادي؟', explain: 'يتطلب التجنس العادي الإقامة المتواصلة في كوريا لمدة 5 سنوات (5년) أو أكثر.' },
  q194: { q: 'بعد كم سنة من الإقامة المتواصلة في كوريا مع استمرار الزواج يمكن للأجنبي المتزوج من كوري التقدم للتجنس المبسَّط؟', explain: 'يمكن للمهاجر بالزواج التقدم للتجنس المبسَّط إذا أقام في كوريا سنتين (2년) متواصلتين أو أكثر مع استمرار الزواج.' },
  q195: { q: 'ما الذي يجب على الأجنبي البالغ 17 عامًا فأكثر أن يحمله دائمًا في كوريا؟', explain: 'يجب على الأجنبي البالغ 17 عامًا فأكثر أن يحمل جواز السفر أو بطاقة تسجيل الأجانب (여권이나 외국인 등록증).' },
  q196: { q: 'ما نوع الإقامة الذي يتيح للأجنبي العيش في كوريا دون تحديد مدة؟', explain: 'من يحصل على الإقامة الدائمة (영주(F-5)) يمكنه العيش في كوريا دون تحديد مدة.' },
  q197: { q: 'ما رقم الهاتف للإبلاغ عن العنف المدرسي أو طلب الاستشارة بشأنه؟', explain: 'يمكن الإبلاغ عن العنف المدرسي إلى مركز الإبلاغ على الرقم 117.' },
  q198: { q: 'ما رقم خط الطوارئ للنساء الذي يقدم استشارات على مدار 24 ساعة لضحايا العنف الأسري أو الجنسي؟', explain: 'يقدم خط الطوارئ للنساء 1366 استشارات لضحايا العنف على مدار 24 ساعة.' },
  q199: { q: 'ماذا يجب أن تفعل أولًا إذا وقع زلزال واهتز المبنى وأنت بداخله؟', explain: 'أثناء الاهتزاز احتمِ تحت طاولة (탁자 밑에서 몸을 보호한다)، وعندما يتوقف الاهتزاز اخرج عبر الدرج.' },
  q200: { q: 'ما الطريقة الصحيحة للإخلاء إلى الخارج عند نشوب حريق في مبنى؟', explain: 'عند الحريق قد يتوقف المصعد، لذا يجب الإخلاء عبر الدرج (계단을 이용한다).' },
  q201: { q: 'ما أول شيء يجب الإبلاغ عنه بدقة عند الاتصال بالرقم 119؟', explain: 'لكي يصل فريق الإنقاذ بسرعة، أخبرهم أولًا بدقة بمكان الحادث (사고가 난 장소).' },
  q202: { q: 'بأي اسم آخر يُسمّى عادةً مركز الإدارة والرعاية (행정복지센터) الذي يتولى الشؤون الإدارية في الحي؟', explain: 'يُسمّى 행정복지센터 أيضًا باسمه القديم مركز السكان (주민센터) أو 동사무소.' },
  q203: { q: 'أين يُقدَّم طلب تسجيل الأجانب لأول مرة؟', explain: 'يُقدَّم طلب تسجيل الأجانب في مكتب الهجرة (출입국·외국인사무소) المختص بمكان السكن.' },
  q204: { q: 'إلى جانب مكتب الهجرة، أين يمكن للأجنبي الإبلاغ عن تغيير محل إقامته بعد الانتقال؟', explain: 'يمكن الإبلاغ عن تغيير محل الإقامة أيضًا في مركز الإدارة والرعاية (행정복지센터) في مكان السكن الجديد.' },
  q205: { q: 'ما الموقع الحكومي الذي يستخدمه الأجانب لتقديم طلبات الإقامة عبر الإنترنت أو حجز موعد في مكتب الهجرة؟', explain: 'يمكن تقديم طلبات الإقامة وحجز المواعيد عبر موقع HiKorea (하이코리아).' },
  q206: { q: 'ما الموقع الحكومي الذي يتيح طلب الوثائق الرسمية مثل نسخة سجل الإقامة وإصدارها عبر الإنترنت؟', explain: 'يمكن إصدار وثائق كثيرة مثل نسخة سجل الإقامة عبر موقع الحكومة 24 (정부24).' },
  q207: { q: 'أيّ مما يلي ليس من مهام 행정복지센터؟', explain: 'يُحصل على إذن تغيير نوع الإقامة (체류 자격 변경 허가) من مكتب الهجرة.' },
  q208: { q: 'الأجنبي الذي لا يعمل في شركة، بعد كم شهرًا من الإقامة في كوريا يجب عليه مبدئيًا الاشتراك في التأمين الصحي؟', explain: 'الأجنبي المقيم 6 أشهر (6개월) أو أكثر يشترك إلزاميًا في التأمين الصحي بصفة مشترك إقليمي.' },
  q209: { q: 'ما الذي يلزم عادةً للاستفادة من التأمين الصحي في مستشفى عام متقدم كالمستشفى الجامعي؟', explain: 'في غير حالات الطوارئ يلزم خطاب إحالة (진료 의뢰서) من عيادة الحي.' },
  q210: { q: 'أين يمكن الحصول على خدمات الصحة العامة بتكلفة منخفضة كالتطعيم والفحص الصحي؟', explain: 'يمكن الحصول على خدمات صحية كالتطعيم في مركز الصحة العامة (보건소) الموجود في كل منطقة.' },
  q211: { q: 'أين تشتري الدواء بالوصفة الطبية التي حصلت عليها من المستشفى؟', explain: 'الأدوية التي تحتاج إلى وصفة تُشترى من الصيدلية (약국) بتقديم الوصفة.' },
  q212: { q: 'ما اسم العيادة التي تعالج بالطب الكوري التقليدي مثل الوخز بالإبر والأعشاب الطبية؟', explain: 'في عيادة الطب الكوري التقليدي (한의원) يمكن تلقي العلاج بالإبر والكيّ والأعشاب الطبية.' },
  q213: { q: 'ماذا قد يحدث للأجنبي الذي لا يدفع أقساط التأمين الصحي باستمرار؟', explain: 'عند التأخر في دفع أقساط التأمين الصحي قد يتعرض الأجنبي لقيود عند تمديد الإقامة (체류 기간 연장이 제한될 수 있다).' },
  q214: { q: 'ما الكيس الذي يجب استخدامه عند التخلص من النفايات العامة؟', explain: 'توضع النفايات العامة في أكياس الرسوم حسب الكمية (종량제 봉투) التي تُباع في المنطقة.' },
  q215: { q: 'أيّ مما يلي لا يجوز التخلص منه مع بقايا الطعام؟', explain: 'الأشياء الصلبة مثل عظام الدجاج (닭 뼈) وأصداف المحار تُرمى مع النفايات العامة.' },
  q216: { q: 'كيف يتم التخلص من الأثاث الكبير مثل السرير أو الأريكة؟', explain: 'يجب الإبلاغ عن الأثاث الكبير كنفايات ضخمة (대형 폐기물로 신고한다) ودفع رسوم للتخلص منه.' },
  q217: { q: 'ماذا يحدث إذا تخلصت من القمامة خلسةً دون استخدام كيس 종량제؟', explain: 'التخلص من القمامة خلسةً قد يعرّضك لغرامة مالية (과태료를 낼 수 있다).' },
  q218: { q: 'ما الطريقة الصحيحة لفرز زجاجات المياه البلاستيكية الشفافة والتخلص منها؟', explain: 'تُفرَغ زجاجات PET الشفافة ويُنزع ملصقها ثم تُجمع وتُرمى على حدة (라벨을 떼고 따로 모아 버린다).' },
  q219: { q: 'ما نظام السكن الذي يُدفع فيه مبلغ تأمين مع إيجار شهري؟', explain: 'نظام وولسيه (월세) هو دفع مبلغ تأمين مع إيجار شهري.' },
  q220: { q: 'ما الذي يحصل عليه المستأجر على عقد الإيجار، إلى جانب تسجيل الانتقال، لحماية مبلغ التأمين؟', explain: 'بعد تسجيل الانتقال والحصول على تاريخ التصديق (확정일자) يصبح للمستأجر حق الأولوية في استرداد التأمين.' },
  q221: { q: 'ما الوثيقة التي يُطّلع عليها قبل توقيع عقد السكن للتأكد من المالك الحقيقي والديون المترتبة على العقار؟', explain: 'من خلال سجل العقار (등기부등본) يمكن معرفة المالك والرهون المترتبة على المنزل.' },
  q222: { q: 'من هو المختص الذي يساعد في إبرام العقد بين المالك والمستأجر عند البحث عن سكن؟', explain: 'الوسيط العقاري المرخَّص (공인 중개사) يتوسط في بيع العقارات وعقود الإيجار.' },
  q223: { q: 'ما الحد الأدنى لمدة العقد المضمونة للمستأجر وفق قانون حماية إيجار المساكن؟', explain: 'حتى لو حُدّدت مدة العقد بأقل من سنتين، يحق للمستأجر السكن لمدة سنتين (2년).' },
  q224: { q: 'لماذا يجب تمرير بطاقة المواصلات على الجهاز عند النزول من الحافلة أيضًا؟', explain: 'يجب تمرير البطاقة عند النزول للحصول على خصم التحويل عند الانتقال إلى حافلة أو مترو آخر (환승 할인을 받기 위해).' },
  q225: { q: 'لمن المقعد الوردي المخصص في المترو؟', explain: 'المقعد الوردي يُترك فارغًا للنساء الحوامل (임산부).' },
  q226: { q: 'ما وثيقة الهوية التي يحتاجها الأجنبي عادةً لفتح حساب مصرفي؟', explain: 'يفتح الأجانب الحساب المصرفي عادةً ببطاقة تسجيل الأجانب (외국인 등록증) أو جواز السفر.' },
  q227: { q: 'ما العبارة الصحيحة بشأن إعارة دفتر الحساب أو بطاقة الخصم الخاصة بك لشخص آخر أو بيعها؟', explain: 'إعارة الحساب المصرفي أو بيعه قد يُستخدم في الجرائم، لذا فهو غير قانوني ويُعاقب عليه (불법이라 처벌받을 수 있다).' },
  q228: { q: 'ما الجهاز الذي يمكن به سحب المال أو إيداعه حتى بعد إغلاق شبابيك البنك؟', explain: 'يمكن بجهاز الصراف الآلي (현금 자동 입출금기) سحب المال أو إيداعه حتى بعد إغلاق شبابيك البنك.' },
  q229: { q: 'ما رقم مركز المعلومات الشامل للأجانب الذي يقدم استشارات الإقامة والتأشيرة بلغات متعددة؟', explain: 'يمكن الحصول على استشارات الإقامة والتأشيرة بلغات متعددة من مركز معلومات الأجانب على الرقم 1345.' },
  q230: { q: 'ما رقم هاتف الإرشاد السياحي الذي يقدم المعلومات والترجمة باللغات الأجنبية؟', explain: 'يقدم الخط 1330 المعلومات السياحية والمساعدة في الترجمة باللغات الأجنبية.' },
  q231: { q: 'ما رقم مركز اتصال دانوري (다누리) الذي يقدم للمهاجرين بالزواج والأسر متعددة الثقافات استشارات حياتية بلغات متعددة؟', explain: 'يقدم مركز اتصال دانوري (1577-1366) استشارات بلغات متعددة للأسر متعددة الثقافات.' },
  q232: { q: 'ما رقم مركز الاتصال الحكومي لإرشاد المواطنين عندما لا تعرف الجهة التي تسألها عن معاملة حكومية؟', explain: 'يقدم مركز الاتصال الحكومي 110 الإرشاد بشأن معاملات جهات حكومية متعددة.' },
  q233: { q: 'ما أول دولة تأسست في تاريخ كوريا؟', explain: 'أول دولة في كوريا هي غوجوسون (고조선) التي أسسها دانغون وانغوم.' },
  q234: { q: 'في أسطورة دانغون، ما الحيوان الذي أكل الشيح والثوم وصبر حتى صار إنسانًا؟', explain: 'الدبّ (곰) أكل الشيح والثوم وصبر حتى صار امرأة اسمها أونغنيو.' },
  q235: { q: 'ما المبدأ الذي قامت عليه غوجوسون ويعني "انفع البشر على نطاق واسع"؟', explain: 'هونغ إيك إنغان (홍익인간) يعني "انفع البشر على نطاق واسع"، وما زال المبدأ الأساسي للتعليم في كوريا حتى اليوم.' },
  q236: { q: 'ما القانون الذي وضعته غوجوسون لحفظ النظام في المجتمع؟', explain: 'كان لدى غوجوسون قانون المواد الثماني (8조법)، وقد وصلت إلينا ثلاث مواد منه.' },
  q237: { q: 'من مؤسس مملكة غوغوريو؟', explain: 'أسس جومونغ (주몽) مملكة غوغوريو.' },
  q238: { q: 'من مؤسس مملكة بيكجي؟', explain: 'أسس أونجو (온조)، ابن جومونغ، مملكة بيكجي في حوض نهر هان.' },
  q239: { q: 'من ملك غوغوريو الذي وسّع أراضيها كثيرًا، وبقيت له مسلّة كبيرة أقامها ابنه؟', explain: 'وسّع الملك غوانغيتو الكبير (광개토대왕) أراضي غوغوريو، وأقام ابنه الملك جانغسو مسلّة تخليدًا له.' },
  q240: { q: 'أيّ الممالك الثلاث (غوغوريو وبيكجي وشيلا) وحّدت الممالك الثلاث؟', explain: 'وحّدت شيلا (신라) الممالك الثلاث عام 676.' },
  q241: { q: 'من القائد الذي كان له فضل كبير في توحيد شيلا للممالك الثلاث؟', explain: 'أدّى القائد كيم يو-شين (김유신) دورًا كبيرًا في توحيد شيلا للممالك الثلاث.' },
  q242: { q: 'ما المعركة التي هزم فيها القائد أولجي مونديوك من غوغوريو جيش أسرة سوي هزيمة كبيرة؟', explain: 'هزم أولجي مونديوك جيش سوي في معركة سالسو الكبرى (살수 대첩) عام 612.' },
  q243: { q: 'ما اتحاد الممالك الذي أنتج الحديد بكثرة وصدّره في منطقة مجرى نهر ناكدونغ الأدنى؟', explain: 'أنتجت غايا (가야) حديدًا جيدًا وصدّرته إلى الدول المجاورة.' },
  q244: { q: 'ما الدولة التي أسسها داي جو-يونغ، المنحدر من غوغوريو، عام 698؟', explain: 'أسس داي جو-يونغ مملكة بالهاي (발해) عام 698 وريثةً لغوغوريو.' },
  q245: { q: 'ماذا تُسمّى الحقبة التي وُجدت فيها شيلا الموحدة في الجنوب وبالهاي في الشمال معًا؟', explain: 'تُسمّى الحقبة التي ضمّت شيلا الموحدة جنوبًا وبالهاي شمالًا حقبة الدولتين الشمالية والجنوبية (남북국 시대).' },
  q246: { q: 'من الذي أسس قاعدة تشونغهيجين وقاد التجارة البحرية في عهد شيلا الموحدة؟', explain: 'أسس جانغ بو-غو (장보고) قاعدة تشونغهيجين في جزيرة واندو وقاد التجارة البحرية.' },
  q247: { q: 'ما المعبد الكهفي الحجري الذي بُني على جبل توهام في غيونغجو في عهد شيلا الموحدة؟', explain: 'سوكغورام (석굴암) معبد كهفي من عهد شيلا الموحدة، وهو مع معبد بولغوكسا من مواقع التراث العالمي لليونسكو.' },
  q248: { q: 'من الذي أسس مملكة غوريو عام 918؟', explain: 'أسس وانغ غون (왕건) مملكة غوريو عام 918 ووحّد الممالك الثلاث اللاحقة.' },
  q249: { q: 'من اسم أي دولة اشتُقّ الاسم الإنجليزي \'Korea\'؟', explain: 'بفضل التجارة النشطة في عهد غوريو (고려) عرف الغرب هذا الاسم فصار \'Korea\'.' },
  q250: { q: 'ما الذي صُنع في عهد غوريو للتغلب على الغزو المغولي بقوة البوذية، ويُحفظ في معبد هايينسا؟', explain: '"بالمان ديجانغ-غيونغ" (팔만대장경) نصوص بوذية محفورة على أكثر من 80 ألف لوح خشبي، وتُحفظ في معبد هايينسا.' },
  q251: { q: 'ما كتاب غوريو الذي يُعدّ أقدم كتاب باقٍ في العالم طُبع بالحروف المعدنية المتحركة؟', explain: 'كتاب جيكجي (직지심체요절) المطبوع بالحروف المعدنية عام 1377 مدرج في سجل ذاكرة العالم لليونسكو.' },
  q252: { q: 'ما كتاب التاريخ الذي كتبه الراهب إيريون في عهد غوريو ويتضمن أسطورة دانغون؟', explain: 'يتضمن كتاب سامغوك يوسا (삼국유사) الذي كتبه إيريون أسطورة دانغون.' },
  q253: { q: 'من القائد الذي هزم جيش الخيتان هزيمة كبيرة في غويجو في عهد غوريو؟', explain: 'هزم كانغ غام-تشان (강감찬) جيش الخيتان في معركة غويجو الكبرى عام 1019.' },
  q254: { q: 'من الذي أسس مملكة جوسون عام 1392؟', explain: 'أسس إي سونغ-غيه (이성계)، أي الملك تيجو، مملكة جوسون عام 1392.' },
  q255: { q: 'ما الاسم الذي كانت تُعرف به عاصمة جوسون، أي سيول الحالية، في ذلك الوقت؟', explain: 'اتخذت جوسون هانيانغ (한양)، أي سيول الحالية، عاصمةً لها.' },
  q256: { q: 'ما سبب ابتكار الملك سيجونغ الكبير لـ"هونمين جونغوم"؟', explain: 'ابتكر الملك سيجونغ أبجدية سهلة ليتمكن عامة الشعب الذين لا يعرفون الحروف الصينية من تعلّمها والكتابة بها بسهولة (백성이 쉽게 배워 쓰게 하려고).' },
  q257: { q: 'ما المعركة البحرية التي هزم فيها القائد إي سون-شين عام 1597 عددًا كبيرًا من السفن اليابانية بعدد قليل من السفن في مضيق أولدولموك؟', explain: 'هزم إي سون-شين عام 1597 في معركة ميونغنيانغ البحرية (명량 해전) البحريةَ اليابانية الأكبر عددًا بكثير بعدد قليل من السفن.' },
  q258: { q: 'ما المؤسسة التي اجتمع فيها كبار العلماء في عهد سيجونغ لدراسة العلوم؟', explain: 'طوّر سيجونغ مؤسسة جيبهيونجون (집현전) ليتفرغ فيها العلماء للبحث.' },
  q259: { q: 'ما الأداة التي صُنعت في عهد سيجونغ لقياس كمية المطر؟', explain: 'الـ"تشوكوغي" (측우기) أداة لقياس كمية المطر صُنعت في عهد سيجونغ.' },
  q260: { q: 'ما الحرب التي اندلعت عندما غزت اليابان جوسون عام 1592؟', explain: 'بدأت حرب إيمجين (임진왜란) بالغزو الياباني عام 1592 واستمرت سبع سنوات.' },
  q261: { q: 'ما المعركة التي هزم فيها القائد إي سون-شين البحرية اليابانية عام 1592 بتشكيل "جناح الكركي"؟', explain: 'انتصر إي سون-شين على البحرية اليابانية انتصارًا كبيرًا في معركة هانسان-دو (한산도 대첩).' },
  q262: { q: 'ما اليوميات التي كتبها القائد إي سون-شين بنفسه خلال حرب إيمجين؟', explain: 'يوميات الحرب "نانجونغ إيلغي" (난중일기) كتبها إي سون-شين أثناء الحرب، وهي مدرجة في سجل ذاكرة العالم لليونسكو.' },
  q263: { q: 'في أي عام انتزعت اليابان بالقوة سيادة الإمبراطورية الكورية (대한제국)؟', explain: 'في عام 1910 (1910년) ضمّت اليابان الإمبراطورية الكورية بالقوة وبدأت حكمها الاستعماري.' },
  q264: { q: 'ما الحكومة التي تأسست في شنغهاي بالصين عام 1919 بعد حركة الأول من مارس؟', explain: 'تأسست الحكومة المؤقتة لجمهورية كوريا (대한민국 임시 정부) في شنغهاي عام 1919 وقادت حركة الاستقلال.' },
  q265: { q: 'من المناضل من أجل الاستقلال الذي قاد الحكومة المؤقتة وكتب 『백범일지』؟', explain: 'كيم غو (김구)، الملقب بيكبوم، مناضل قاد الحكومة المؤقتة وترك كتاب 『백범일지』.' },
  q266: { q: 'من الطالبة المناضلة التي قادت هتافات "مانسيه" للاستقلال في سوق أوناي بمدينة تشونان خلال حركة الأول من مارس؟', explain: 'قادت يو غوان-سون (유관순) هتافات سوق أوناي وتوفيت في السجن.' },
  q267: { q: 'من المناضل الذي أطلق النار على إيتو هيروبومي في هاربين بالصين عام 1909؟', explain: 'أطلق آن جونغ-غون (안중근) النار على إيتو هيروبومي في محطة هاربين عام 1909.' },
  q268: { q: 'ما الوثيقة التي أعلنها ممثلو الأمة الثلاثة والثلاثون خلال حركة الأول من مارس؟', explain: 'أعلن الممثلون الثلاثة والثلاثون إعلان الاستقلال (독립 선언서) ليُعلموا العالم باستقلال كوريا.' },
  q269: { q: 'ما المعركة التي هزم فيها جيش الاستقلال بقيادة القائد كيم جوا-جين الجيشَ الياباني في منشوريا عام 1920؟', explain: 'انتصر جيش الاستقلال على الجيش الياباني انتصارًا كبيرًا في معركة تشونغسانري (청산리 대첩) عام 1920.' },
  q270: { q: 'متى تأسست حكومة جمهورية كوريا؟', explain: 'تأسست حكومة جمهورية كوريا في 15 أغسطس 1948 (1948년 8월 15일).' },
  q271: { q: 'من أول رئيس لجمهورية كوريا؟', explain: 'في عام 1948 أصبح سينغمان ري (이승만) أول رئيس لكوريا.' },
  q272: { q: 'ماذا يُسمّى البرلمان الذي تشكّل بانتخابات 10 مايو 1948 العامة ووضع الدستور؟', explain: 'وضع المجلس التأسيسي (제헌 국회) المنتخب في 10 مايو الدستورَ عام 1948.' },
  q273: { q: 'ما الخط الذي قسّمت به الولايات المتحدة والاتحاد السوفيتي شبه الجزيرة الكورية إلى شمال وجنوب بعد التحرير مباشرة؟', explain: 'بعد التحرير أدارت الولايات المتحدة الجنوب والاتحاد السوفيتي الشمال، وكان خط العرض 38 (38도선) هو الحد الفاصل.' },
  q274: { q: 'في أي عام وُقّعت اتفاقية الهدنة في الحرب الكورية (6·25)؟', explain: 'في 27 يوليو 1953 (1953년) وُقّعت اتفاقية الهدنة وتوقف القتال.' },
  q275: { q: 'ما العملية التي غيّرت بها قوات الأمم المتحدة مجرى الحرب الكورية (6·25) في سبتمبر 1950؟', explain: 'بفضل عملية الإنزال في إنتشون (인천 상륙 작전) في 15 سبتمبر 1950 استعاد الجيش الكوري وقوات الأمم المتحدة سيول.' },
  q276: { q: 'أين وُقّعت اتفاقية الهدنة في الحرب الكورية (6·25)؟', explain: 'وُقّعت اتفاقية الهدنة في بانمونجوم (판문점) عام 1953.' },
  q277: { q: 'ماذا تُسمّى العائلات التي تفرّقت ولا تعرف أخبار بعضها بسبب الحرب الكورية (6·25) وتقسيم الكوريتين؟', explain: 'تُسمّى العائلات التي فرّقتها الحرب والتقسيم "العائلات المشتتة" (이산가족)، وقد نظّمت الكوريتان لقاءات للمّ شملها.' },
  q278: { q: 'ما الثورة الديمقراطية التي قام بها الطلاب والمواطنون ضد تزوير انتخابات 15 مارس 1960؟', explain: 'أدّت ثورة 19 أبريل (4·19 혁명) إلى تنحّي الرئيس سينغمان ري.' },
  q279: { q: 'ما الحركة الديمقراطية التي قام بها مواطنو غوانغجو ضد الديكتاتورية العسكرية في مايو 1980؟', explain: 'وقعت حركة 18 مايو الديمقراطية (5·18 민주화 운동) في غوانغجو عام 1980، ووثائقها مدرجة في سجل ذاكرة العالم لليونسكو.' },
  q280: { q: 'ما الحركة الديمقراطية التي قام بها المواطنون في أنحاء البلاد في يونيو 1987 مطالبين بانتخاب الرئيس مباشرة؟', explain: 'نتيجة لانتفاضة يونيو الديمقراطية (6월 민주 항쟁) أصبح الشعب ينتخب الرئيس مباشرة.' },
  q281: { q: 'ما المدينة التي التقى فيها زعيما الكوريتين لأول مرة في قمة عام 2000؟', explain: 'في يونيو 2000 عُقدت أول قمة بين الكوريتين في بيونغ يانغ (평양) وصدر الإعلان المشترك في 15 يونيو.' },
  q282: { q: 'إلى أي بلد أرسلت كوريا عمال المناجم والممرضات في الستينيات والسبعينيات لكسب العملة الأجنبية؟', explain: 'ساهمت الأموال التي أرسلها عمال المناجم والممرضات العاملون في ألمانيا الغربية (서독) في التنمية الاقتصادية لكوريا.' },
  q283: { q: 'ما الطريق السريع الذي افتُتح عام 1970 ويربط سيول ببوسان؟', explain: 'أدّى طريق غيونغبو السريع (경부 고속도로)، الذي افتُتح عام 1970، دورًا كبيرًا في التصنيع والنمو الاقتصادي.' },
  q284: { q: 'من الرئيس الذي كان أول كوري يفوز بجائزة نوبل للسلام؟', explain: 'حصل الرئيس كيم داي-جونغ (김대중) على جائزة نوبل للسلام عام 2000 لجهوده من أجل الديمقراطية والمصالحة بين الكوريتين.' },
  q285: { q: 'ما الطعام الذي يُؤكل صباح عيد رأس السنة القمرية (سولال) ويُقال عنه إنه "يزيد العمر سنة"؟', explain: 'في عيد سولال يأكل الكوريون حساء كعك الأرز "تتوكغوك" (떡국) ويقولون إنهم كبروا سنة.' },
  q286: { q: 'ماذا يُسمّى أول عيد ميلاد للطفل بعد ولادته؟', explain: 'يُسمّى أول عيد ميلاد للطفل "دول" (돌)، وتُقام له حفلة تُسمّى دولجانتشي.' },
  q287: { q: 'ما العادة التي تُمارس في حفلة عيد الميلاد الأول، حيث يختار الطفل شيئًا مثل الخيط أو القلم أو المال للتنبؤ بمستقبله؟', explain: 'في طقس "دولجابي" (돌잡이) يُتنبأ بمستقبل الطفل من الشيء الذي يمسكه.' },
  q288: { q: 'ما الطقس الذي تُقدَّم فيه الأطعمة للأجداد صباح عيد سولال أو تشوسوك؟', explain: 'يُسمّى الطقس الذي يُقام للأجداد صباح الأعياد "تشاريه" (차례).' },
  q289: { q: 'ما الطقس الذي يُقام في ذكرى وفاة الأجداد تخليدًا لذكراهم؟', explain: 'يُسمّى الطقس الذي يُقام في يوم وفاة الأجداد "جيسا" (제사).' },
  q290: { q: 'ماذا تُسمّى زيارة قبور الأجداد في الأعياد لتحيتهم والعناية بها؟', explain: 'تُسمّى زيارة قبور الأجداد والعناية بها "سونغميو" (성묘).' },
  q291: { q: 'ما الطعام التقليدي الذي يُؤكل في يوم الانقلاب الشتوي، صاحب أطول ليلة في السنة؟', explain: 'في يوم الانقلاب الشتوي يأكل الكوريون عصيدة الفاصوليا الحمراء "باتجوك" (팥죽) لطرد الشرور.' },
  q292: { q: 'ما الاسم الكوري الأصيل الآخر لعيد تشوسوك (추석)؟', explain: 'يوافق تشوسوك اليوم الخامس عشر من الشهر الثامن بالتقويم القمري، ويُسمّى أيضًا "هانغاوي" (한가위).' },
  q293: { q: 'ما الحساء الذي يأكله الكوريون عادةً صباح يوم الميلاد؟', explain: 'نشأت عادة أكل حساء الأعشاب البحرية "ميوكغوك" (미역국) في عيد الميلاد من تناول الأمهات له بعد الولادة.' },
  q294: { q: 'ما الطعام الذي يُؤكل في أيام "بوكنال" الصيفية لمقاومة الحر، ويُطهى فيه دجاج صغير مع الجينسنغ والأرز اللزج؟', explain: 'في أيام بوكنال يكثر الكوريون من أكل "سامغيتانغ" (삼계탕) لتقوية الجسم.' },
  q295: { q: 'ما الطعام الذي توضع فيه أنواع من الخضار واللحم ومعجون الفلفل الأحمر فوق الأرز ثم يُخلط ويُؤكل؟', explain: 'البيبيمباب (비빔밥) طبق يُخلط فيه الأرز مع الخضار ومعجون الفلفل وغيرها.' },
  q296: { q: 'ما المعجون التقليدي الأحمر الحار المصنوع من مسحوق الفلفل الأحمر والأرز اللزج ومسحوق فول الصويا المخمّر؟', explain: 'الغوتشوجانغ (고추장) معجون أحمر حار مصنوع من مسحوق الفلفل الأحمر.' },
  q297: { q: 'ما آداب الطعام الصحيحة عند تناول الطعام مع كبار السن؟', explain: 'من الآداب أن تنتظر حتى يرفع الكبير ملعقته وعيدانه أولًا ثم تبدأ الأكل (어른이 먼저 수저를 든 뒤에 먹는다).' },
  q298: { q: 'ما التصرف الصحيح عند إعطاء شيء لكبير السن أو أخذه منه؟', explain: 'من الأدب أن تعطي الكبار الأشياء وتأخذها منهم بكلتا اليدين (두 손으로 드리고 받는다).' },
  q299: { q: 'ما صيغة الاحترام لكلمة \'나이\' (العمر)؟', explain: 'صيغة الاحترام لـ\'나이\' هي "يونسيه" (연세)، مثل: "연세가 어떻게 되세요?" (كم عمر حضرتك؟).' },
  q300: { q: 'ما صيغة الاحترام للفعل \'자다\' (ينام)؟', explain: 'عند الحديث عن نوم الكبار تُستخدم صيغة الاحترام "جوموسيدا" (주무시다).' },
  q301: { q: 'منذ يونيو 2023، ما طريقة حساب العمر المعتمدة أساسًا في القانون والإدارة؟', explain: 'منذ يونيو 2023 يُعتمد أساسًا في القانون والإدارة العمر الكامل (만 나이) المحسوب من تاريخ الميلاد.' },
  q302: { q: 'ماذا يُسمّى التعبير عن سنة الميلاد باثني عشر حيوانًا مثل الفأر والثور والنمر؟', explain: 'في كوريا يُعبَّر عن سنة الميلاد بأحد الحيوانات الاثني عشر، ويُسمّى ذلك "تي" (띠).' },
  q303: { q: 'ماذا يُسمّى عيد الميلاد الذي يبلغ فيه الشخص ستين عامًا كاملة؟', explain: 'يُسمّى عيد الميلاد الستون "هوانغاب" (환갑)، وكانت تُقام له قديمًا حفلة كبيرة.' },
  q304: { q: 'ما الفن التقليدي الذي يروي فيه مغنٍّ واحد قصة طويلة بالغناء والكلام والحركات على إيقاع عازف الطبل؟', explain: 'البانسوري (판소리) فن تقليدي يؤديه مغنٍّ وعازف طبل، وهو مدرج في قائمة اليونسكو للتراث الثقافي غير المادي للبشرية.' },
  q305: { q: 'ما الموسيقى التقليدية التي تُعزف بأربع آلات هي: كوينغواري وجينغ وجانغو وبوك؟', explain: 'السامولنوري (사물놀이) موسيقى تقليدية مفعمة بالحيوية تُعزف بأربع آلات إيقاعية.' },
  q306: { q: 'ما الأغنية الشعبية التي تمثل كوريا وتتوارث بأشكال مختلفة في كل منطقة؟', explain: 'أريرانغ (아리랑) أغنية شعبية تمثل كوريا، وهي مدرجة في قائمة اليونسكو للتراث الثقافي غير المادي للبشرية.' },
  q307: { q: 'ما العرض التقليدي الذي يرتدي فيه المؤدّون الأقنعة ويرقصون ويغنّون ويروون قصصًا تسخر أحيانًا من طبقة النبلاء (يانغبان)؟', explain: 'التالتشوم (탈춤) عرض تقليدي بالأقنعة، أُدرج عام 2022 في قائمة اليونسكو للتراث الثقافي غير المادي.' },
  q308: { q: 'ما اللعبة التقليدية التي تمسك فيها النساء بأيدي بعضهن ويدرن في دائرة وهنّ يغنين ويرقصن في ليلة تشوسوك؟', explain: 'الغانغانغسولي (강강술래) لعبة تقليدية تُؤدّى تحت البدر في ليلة تشوسوك، وهي مدرجة في قائمة اليونسكو للتراث غير المادي.' },
  q309: { q: 'ما المكان الذي كانت تُحفظ فيه ألواح أرواح ملوك جوسون وملكاتها وتُقام فيه الطقوس، وهو من مواقع التراث العالمي لليونسكو؟', explain: 'جونغميو (종묘) معبد أسلاف الأسرة الملكية في جوسون، وأُدرج في قائمة التراث العالمي لليونسكو عام 1995.' },
  q310: { q: 'ما الحصن الذي بناه الملك جونغجو من جوسون في سوون، وهو من مواقع التراث العالمي لليونسكو؟', explain: 'حصن هواسونغ في سوون (수원 화성) بُني في عهد الملك جونغجو، وأصبح من مواقع التراث العالمي لليونسكو عام 1997.' },
  q311: { q: 'أيّ قصور سيول أُدرج في قائمة التراث العالمي لليونسكو؟', explain: 'قصر تشانغدوكغونغ (창덕궁) يتناغم مع الطبيعة، وأصبح من مواقع التراث العالمي لليونسكو عام 1997.' },
  q312: { q: 'ما الكتاب الذي سجّل أعمال ملوك جوسون في الحكم بترتيب زمني، وهو مدرج في سجل ذاكرة العالم لليونسكو؟', explain: 'سجلات أسرة جوسون الملكية (조선왕조실록) كتاب تاريخ يوثّق أعمال ملوك جوسون، وأُدرج في سجل ذاكرة العالم لليونسكو عام 1997.' },
  q313: { q: 'ماذا تُسمّى ظاهرة انتشار الدراما والأفلام والموسيقى الشعبية الكورية حول العالم؟', explain: 'تُسمّى ظاهرة انتشار الثقافة الشعبية الكورية عالميًا "هاليو" (한류) أي الموجة الكورية.' },
  q314: { q: 'ما البطولة الرياضية الدولية التي استضافتها كوريا واليابان معًا عام 2002؟', explain: 'في كأس العالم (월드컵) 2002 بكوريا واليابان وصلت كوريا إلى الدور نصف النهائي.' },
  q315: { q: 'ما الحدث الرياضي الدولي الذي أُقيم في بيونغتشانغ بمقاطعة غانغوون عام 2018؟', explain: 'كانت دورة الألعاب الأولمبية الشتوية (동계 올림픽) في بيونغتشانغ 2018 أول أولمبياد شتوي يُقام في كوريا.' },
  q316: { q: 'من الكاتب الذي أصبح عام 2024 أول كوري يفوز بجائزة نوبل للآداب؟', explain: 'فازت الروائية هان كانغ (한강) بجائزة نوبل للآداب عام 2024 لتكون أول كورية تنالها.' },
  q317: { q: 'ما الخطة التي وضعتها الحكومة على مراحل مدة كل منها خمس سنوات لتنمية الاقتصاد منذ ستينيات القرن العشرين؟', explain: 'بدأت الحكومة منذ عام 1962 خطط التنمية الاقتصادية الخمسية (경제 개발 5개년 계획) لقيادة النمو الاقتصادي.' },
  q318: { q: 'ما اسم الصناعات مثل الصلب وبناء السفن والكيماويات التي ركّزت الحكومة على تطويرها في السبعينيات؟', explain: 'في السبعينيات طوّرت كوريا الصناعات الثقيلة والكيماوية (중화학 공업) مثل الصلب وبناء السفن والبتروكيماويات.' },
  q319: { q: 'ما الحملة التي شارك فيها المواطنون معًا للتغلب على أزمة العملة الأجنبية عام 1997؟', explain: 'تبرّع المواطنون بالذهب الذي في بيوتهم لمساعدة البلاد في حملة جمع الذهب (금 모으기 운동).' },
  q320: { q: 'ما المنظمة الدولية التي أقرضت كوريا أموالًا طارئة أثناء أزمة العملة الأجنبية عام 1997؟', explain: 'حصلت كوريا على دعم صندوق النقد الدولي (국제통화기금, IMF)، لذلك تُسمّى الأزمة أيضًا «أزمة صندوق النقد».' },
  q321: { q: 'ما منظمة التعاون الاقتصادي التي تضم في الغالب الدول المتقدمة وانضمت إليها كوريا عام 1996؟', explain: 'انضمت كوريا عام 1996 إلى منظمة التعاون الاقتصادي والتنمية (경제협력개발기구, OECD).' },
  q322: { q: 'ما الصحيح بشأن سمات الاقتصاد الكوري الذي يملك موارد طبيعية قليلة؟', explain: 'كوريا اقتصاد قائم على التجارة: تستورد المواد الخام وتصنع المنتجات وتصدّرها (수출과 무역의 비중이 크다).' },
  q323: { q: 'ما مصدر الطاقة الذي تستورده كوريا كله تقريبًا من الخارج؟', explain: 'لا تكاد كوريا تنتج النفط، لذلك تستورد معظم النفط الخام (원유).' },
  q324: { q: 'ما الاتفاقية التي تعقدها الدول لخفض الرسوم الجمركية أو إلغائها وتحرير التجارة؟', explain: 'اتفاقية التجارة الحرة (자유 무역 협정, FTA) تعهّد بين الدول بخفض الرسوم الجمركية لزيادة التجارة.' },
  q325: { q: 'ما المنتج الذي لا غنى عنه في الحواسيب والهواتف الذكية ويُعدّ من أهم صادرات كوريا؟', explain: 'أشباه الموصلات (반도체) صناعة تصدير رئيسية تتصدّر فيها كوريا العالم.' },
  q326: { q: 'ما الصناعة التي تبني السفن الكبيرة وتتمتع فيها كوريا بقدرة تنافسية عالمية؟', explain: 'صناعة بناء السفن (조선업) هي صناعة صنع السفن، وكوريا من الدول الرائدة عالميًا فيها.' },
  q327: { q: 'ما المدينة الصناعية الأبرز في كوريا التي تزدهر فيها صناعة السيارات وبناء السفن والبتروكيماويات؟', explain: 'أولسان (울산) مدينة صناعية تتجمع فيها مصانع السيارات والسفن والبتروكيماويات.' },
  q328: { q: 'ما المدينة الواقعة على الساحل الشرقي والمشهورة بصناعة الصلب لوجود مصنع حديد كبير فيها؟', explain: 'في بوهانغ (포항) مصنع حديد كبير، لذلك تطورت فيها صناعة الصلب.' },
  q329: { q: 'ما المنتج الصناعي الكوري الرئيسي الذي يُصنع في مصانع كبيرة في أولسان وآسان وغوانغجو ويُصدَّر إلى دول كثيرة؟', explain: 'السيارات (자동차) من أبرز صادرات كوريا إلى جانب أشباه الموصلات والسفن.' },
  q330: { q: 'أيّ مما يلي ليس من الصادرات الرئيسية لكوريا؟', explain: 'حبوب القهوة (커피 원두) لا تكاد تُزرع في كوريا، فهي سلعة مستوردة.' },
  q331: { q: 'ما النظام الاقتصادي في كوريا؟', explain: 'تتبع كوريا اقتصاد السوق (시장 경제) الذي يحترم الحرية الاقتصادية للأفراد والشركات.' },
  q332: { q: 'في اقتصاد السوق، بماذا تتحدد أسعار السلع في الغالب؟', explain: 'في السوق تتحدد الأسعار وفق العرض والطلب (수요와 공급).' },
  q333: { q: 'إذا كثر الراغبون في شراء سلعة ما وكانت السلعة قليلة، فماذا يحدث لسعرها عادةً؟', explain: 'عندما يزيد الطلب على العرض يرتفع السعر (오른다).' },
  q334: { q: 'ماذا تُسمّى ظاهرة الارتفاع المستمر في الأسعار؟', explain: 'يُسمّى الارتفاع المستمر في الأسعار التضخم (인플레이션).' },
  q335: { q: 'ما الجهة الحكومية التي تراقب ما إذا كانت الشركات تتنافس بنزاهة؟', explain: 'تمنع لجنة التجارة العادلة (공정거래위원회) الممارسات التجارية غير العادلة والتواطؤ بين الشركات.' },
  q336: { q: 'ماذا تُسمّى النسبة التي تُبادَل بها عملة بلدنا بالعملات الأجنبية؟', explain: 'سعر الصرف (환율) هو نسبة تبادل الوون بالعملات الأجنبية، ويتغير كل يوم.' },
  q337: { q: 'ما الضريبة التي تُدفع على المال المكتسب من العمل (الدخل)؟', explain: 'من لديه دخل يدفع ضريبة الدخل (소득세).' },
  q338: { q: 'ما الضريبة المضمّنة في السعر وتُدفع معه عند شراء سلعة أو استخدام خدمة؟', explain: 'ضريبة القيمة المضافة (부가가치세) مضمّنة في سعر السلعة ويدفعها المستهلك.' },
  q339: { q: 'ما الضريبة المفروضة على السلع عند استيرادها من الخارج؟', explain: 'تُفرض الرسوم الجمركية (관세) على السلع المستوردة.' },
  q340: { q: 'ما الجهة الإدارية المركزية التي تجبي الضرائب المدفوعة للدولة (الضرائب الوطنية) وتديرها؟', explain: 'مصلحة الضرائب الوطنية (국세청) تجبي الضرائب الوطنية مثل ضريبة الدخل وضريبة القيمة المضافة.' },
  q341: { q: 'ماذا تُسمّى إعادة حساب الضرائب التي دفعها الموظف خلال السنة، فيستردّ الزائد ويدفع الناقص؟', explain: 'التسوية الضريبية السنوية (연말정산) إجراء لإعادة حساب ضرائب السنة كاملة.' },
  q342: { q: 'أيّ مما يلي ليس من التأمينات الاجتماعية الأربعة في كوريا؟', explain: 'التأمينات الاجتماعية الأربعة هي المعاش الوطني والتأمين الصحي وتأمين التوظيف وتأمين إصابات العمل، أما تأمين السفر (여행자 보험) فتأمين خاص.' },
  q343: { q: 'ما التأمين الذي يقدّم تعويضًا عند الإصابة أثناء العمل أو المرض بسبب العمل؟', explain: 'تأمين إصابات العمل (산재보험) يحمي العامل الذي يُصاب أو يمرض بسبب العمل.' },
  q344: { q: 'ما التأمين الذي يتيح الحصول على إعانة البطالة أثناء البحث عن عمل جديد بعد ترك الشركة؟', explain: 'من اشترك في تأمين التوظيف (고용보험) يمكنه الحصول على إعانة البطالة إذا استوفى الشروط.' },
  q345: { q: 'من يدفع اشتراك تأمين إصابات العمل (산재보험)؟', explain: 'يدفع صاحب العمل اشتراك تأمين إصابات العمل كاملًا (사업주가 모두 낸다).' },
  q346: { q: 'من يدفع عادةً اشتراك التأمين الصحي للشخص الذي يعمل في شركة؟', explain: 'تدفع الشركة والعامل اشتراك التأمين الصحي مناصفةً (회사와 근로자가 반씩 낸다).' },
  q347: { q: 'ما الهيئة العامة التي تجمع اشتراكات التأمين الصحي وتنظّم الفحوص الصحية الوطنية؟', explain: 'تتولى هيئة التأمين الصحي الوطني (국민건강보험공단) شؤون التأمين الصحي والفحوص الصحية.' },
  q348: { q: 'إلى أي هيئة عامة يُقدَّم طلب تعويض تأمين إصابات العمل عند الإصابة أثناء العمل؟', explain: 'يُقدَّم طلب تعويض إصابات العمل إلى هيئة رعاية العمال (근로복지공단).' },
  q349: { q: 'ما المعاش الذي تحصل عليه الأسرة عند وفاة المشترك في المعاش الوطني؟', explain: 'عند وفاة المشترك يمكن لأسرته الحصول على معاش الورثة (유족연금).' },
  q350: { q: 'ما النظام الذي يدعم ذوي الظروف الصعبة بنفقات المعيشة والعلاج لضمان الحد الأدنى من الحياة الكريمة؟', explain: 'نظام ضمان المعيشة الأساسية الوطني (국민기초생활보장 제도) تدعم فيه الدولة المعيشة الأساسية للمحتاجين.' },
  q351: { q: 'ما المعاش الذي تدفعه الدولة شهريًا لكبار السن ذوي الدخل المنخفض؟', explain: 'المعاش الأساسي (기초연금) تمنحه الدولة لمساعدة كبار السن ذوي الظروف الصعبة.' },
  q352: { q: 'ما التأمين الذي يقدم خدمات الرعاية لمن يصعب عليهم العيش بمفردهم بسبب الشيخوخة أو أمراضها؟', explain: 'تأمين الرعاية طويلة الأمد لكبار السن (노인장기요양보험) يقدّم الرعاية المنزلية وغيرها.' },
  q353: { q: 'ما المال الذي تدفعه الدولة شهريًا للأسر التي تربي أطفالًا؟', explain: 'إعانة الطفل (아동수당) مال تمنحه الدولة لتخفيف عبء تربية الأطفال.' },
  q354: { q: 'ما النظام الذي يتيح التوقف عن العمل مدة معينة لتربية طفل صغير؟', explain: 'إجازة رعاية الطفل (육아 휴직) نظام للتوقف عن العمل مدة معينة لرعاية الطفل، ويحق للأم والأب كليهما.' },
  q355: { q: 'عند إيداع المال في البنك، ما المال الذي يدفعه البنك مقابل ذلك؟', explain: 'عند الإيداع في البنك تحصل على الفائدة (이자).' },
  q356: { q: 'ما المنتج المصرفي الذي يُودَع فيه مبلغ ثابت كل شهر لتكوين مبلغ كبير؟', explain: 'الادخار الشهري (적금) إيداع شهري يُستردّ مع الفائدة عند انتهاء المدة.' },
  q357: { q: 'ماذا يُسمّى اقتراض المال من البنك؟', explain: 'يُسمّى اقتراض المال من البنك قرضًا (대출)، ويجب سداده مع الفائدة.' },
  q358: { q: 'ماذا يُسمّى تحويل العملة الكورية إلى عملة أجنبية مثل الدولار؟', explain: 'يُسمّى تبديل المال بعملة بلد آخر صرف العملات (환전).' },
  q359: { q: 'من الشخصية المرسومة على ورقة الخمسين ألف وون؟', explain: 'على ورقة الخمسين ألف وون صورة شين سا-إيم-دانغ (신사임당)، الفنانة من عهد جوسون.' },
  q360: { q: 'ما البطاقة التي يُخصم بها ثمن المشتريات من حسابي المصرفي فورًا؟', explain: 'بطاقة الخصم (체크카드) تخصم من الحساب فورًا، أما بطاقة الائتمان فيُدفع بها لاحقًا.' },
  q361: { q: 'ما النظام الذي يعيد الودائع حتى المبلغ المحدد قانونًا حتى لو أغلق البنك؟', explain: 'نظام حماية المودعين (예금자 보호 제도) يحمي الودائع حتى مبلغ معين حتى لو أفلس البنك.' },
  q362: { q: 'ما الاحتيال الذي ينتحل فيه شخص صفة النيابة أو موظف البنك ويطلب عبر الهاتف تحويل المال؟', explain: 'إذا اشتبهت في احتيال هاتفي (보이스피싱) فلا تحوّل المال وأبلغ الرقم 112.' },
  q363: { q: 'ما الجهة التي يمكن الحصول منها على استشارة ومساعدة عند التضرر من سلعة أو خدمة؟', explain: 'تساعد الوكالة الكورية للمستهلك (한국소비자원) في استشارات أضرار المستهلكين وحلّها.' },
  q364: { q: 'السلع المشتراة عبر الإنترنت، خلال كم يومًا من استلامها يمكن من حيث المبدأ إلغاء الشراء (إرجاعها)؟', explain: 'في التسوق عبر الإنترنت يمكن مبدئيًا الإلغاء خلال 7 أيام (7일) من استلام السلعة.' },
  q365: { q: 'ما طريقة استئجار السكن الكورية التي يُودَع فيها مبلغ تأمين كبير لدى المالك دون دفع إيجار شهري؟', explain: 'الجونسي (전세) إيداع مبلغ تأمين والسكن به، ثم استرداده عند انتهاء العقد.' },
  q366: { q: 'ما المال الذي تدفعه الشركة للعامل الذي عمل سنة أو أكثر عند تركه العمل؟', explain: 'العامل الذي عمل سنة متواصلة أو أكثر يحصل على مكافأة نهاية الخدمة (퇴직금) عند ترك العمل.' },
  q367: { q: 'ما النظام الذي تسمح بموجبه الحكومة للعمال الأجانب بالعمل بشكل قانوني في الشركات الكورية؟', explain: 'نظام تصاريح التوظيف (고용허가제) يتيح للشركات التي تعاني نقص العمالة توظيف عمال أجانب بإذن حكومي.' },
  q368: { q: 'ماذا تُسمّى حالة الشخص القادر على العمل والراغب فيه لكنه لا يجد وظيفة؟', explain: 'تُسمّى حالة الرغبة في العمل مع عدم وجود وظيفة البطالة (실업).' },
  q369: { q: 'في شرق أيّ قارة تقع جمهورية كوريا؟', explain: 'تقع كوريا في شبه الجزيرة الكورية شرق قارة آسيا (아시아).' },
  q370: { q: 'ما الدولة المجاورة الواقعة شرق كوريا ويفصل بينهما البحر الشرقي (동해)؟', explain: 'اليابان (일본) دولة مجاورة تقع شرق كوريا عبر البحر الشرقي.' },
  q371: { q: 'ما النهران اللذان يشكّلان الحدود الشمالية لشبه الجزيرة الكورية؟', explain: 'يحدّ شمالَ شبه الجزيرة نهرا يالو وتومن (압록강과 두만강) مع الصين وروسيا.' },
  q372: { q: 'ماذا تُسمّى المنطقة الممتدة على طول خط الهدنة التي اتُّفق على عدم نشر قوات عسكرية فيها من الجانبين؟', explain: 'تُسمّى المنطقة الخالية من القوات حول خط الهدنة المنطقة منزوعة السلاح (비무장 지대, DMZ).' },
  q373: { q: 'كم كيلومترًا تمتد المنطقة منزوعة السلاح (DMZ) جنوبًا وشمالًا من خط الترسيم العسكري في كل جانب؟', explain: 'تمتد المنطقة منزوعة السلاح كيلومترين (2km) من كل جانب لخط الترسيم، بعرض إجمالي نحو 4 كم.' },
  q374: { q: 'ما المكان الواقع على خط الترسيم العسكري الذي توجد فيه منطقة الأمن المشتركة وعُقدت فيه محادثات بين الكوريتين؟', explain: 'في بانمونجوم (판문점) منطقة الأمن المشتركة (JSA)، وقد عُقدت فيها محادثات بين الكوريتين.' },
  q375: { q: 'بماذا تشتهر اليوم المنطقة منزوعة السلاح التي ظل دخول الناس إليها مقيدًا لفترة طويلة؟', explain: 'لأن الإنسان لم يمسّها، أصبحت المنطقة منزوعة السلاح مكانًا يُحفظ فيه النظام البيئي الطبيعي جيدًا (자연 생태계가 잘 보존된 곳).' },
  q376: { q: 'ما إقليم جمهورية كوريا كما حدده الدستور؟', explain: 'تنص المادة 3 من الدستور على أن الإقليم هو شبه الجزيرة الكورية والجزر التابعة لها (한반도와 그 부속 도서).' },
  q377: { q: 'ما نوع التضاريس الذي يشغل نحو 70% من أراضي كوريا؟', explain: 'نحو 70% من أراضي كوريا مناطق جبلية (산지).' },
  q378: { q: 'ما الصحيح بشأن سمات تضاريس كوريا؟', explain: 'تكثر الجبال العالية في شرق كوريا وتنخفض الأرض نحو الغرب (동쪽이 높고 서쪽이 낮다).' },
  q379: { q: 'ماذا تُسمّى السلسلة الجبلية الكبيرة الممتدة من جبل بيكدو إلى جبل جيري عبر شبه الجزيرة من الشمال إلى الجنوب؟', explain: 'بيكدو-دايغان (백두대간) سلسلة جبلية كبرى تُعدّ العمود الفقري لشبه الجزيرة.' },
  q380: { q: 'في أي مقاطعة يقع جبل سوراك؟', explain: 'يقع جبل سوراك في شرق مقاطعة غانغوون ذات الحكم الذاتي الخاص (강원특별자치도).' },
  q381: { q: 'ما الجبل الذي أُعلن أول حديقة وطنية في كوريا؟', explain: 'أصبح جبل جيري (지리산) أول حديقة وطنية في كوريا عام 1967.' },
  q382: { q: 'ما أطول نهر في كوريا الجنوبية؟', explain: 'نهر ناكدونغ (낙동강) أطول نهر في كوريا الجنوبية ويصبّ في البحر الجنوبي.' },
  q383: { q: 'ما أوسع سهل في كوريا، وهو منطقة رئيسية لإنتاج الأرز؟', explain: 'سهل هونام (호남평야) أوسع سهل في كوريا وتزدهر فيه زراعة الأرز.' },
  q384: { q: 'كيف تكوّنت جزيرة جيجو؟', explain: 'جيجو جزيرة بركانية تكوّنت بفعل النشاط البركاني (화산 활동).' },
  q385: { q: 'ما الجزيرتان الكبيرتان اللتان تتكوّن منهما دوكدو؟', explain: 'تتكوّن دوكدو من الجزيرة الشرقية والجزيرة الغربية (동도와 서도) وصخور صغيرة حولهما.' },
  q386: { q: 'ما أقرب جزيرة كورية كبيرة إلى دوكدو؟', explain: 'جزيرة أولونغ (울릉도) تقع في البحر الشرقي وهي الأقرب إلى دوكدو.' },
  q387: { q: 'ما أكبر جزيرة في كوريا؟', explain: 'جزيرة جيجو (제주도) أكبر جزيرة في كوريا، وتتبع مقاطعة جيجو ذات الحكم الذاتي الخاص.' },
  q388: { q: 'ما الصحيح بشأن مناخ كوريا؟', explain: 'في كوريا أربعة فصول واضحة (사계절이 뚜렷하다): الربيع والصيف والخريف والشتاء.' },
  q389: { q: 'من أي اتجاه تهب غالبًا الرياح الباردة والجافة على كوريا في الشتاء؟', explain: 'في الشتاء تهب الرياح الموسمية من الشمال الغربي (북서쪽) قادمة من القارة، فيكون الجو باردًا وجافًا.' },
  q390: { q: 'ما الظاهرة التي تجلب الرياح القوية والأمطار الغزيرة بين الصيف وأوائل الخريف؟', explain: 'الإعصار (태풍) يجلب رياحًا قوية وأمطارًا غزيرة في الصيف وأوائل الخريف.' },
  q391: { q: 'ما الغبار الرملي الأصفر الذي يأتي في الربيع من صحارى الصين ومنغوليا؟', explain: 'يُسمّى الغبار الأصفر القادم من الصحارى في الربيع الغبار الأصفر (황사).' },
  q392: { q: 'ما المصطلح الذي يصف طقس الشتاء بمعنى «ثلاثة أيام باردة وأربعة أيام دافئة»؟', explain: 'سامهان-ساون (삼한사온) ظاهرة تتناوب فيها الأيام الباردة والدافئة في الشتاء.' },
  q393: { q: 'ما الصحيح بشأن سمات البحر الشرقي (동해)؟', explain: 'البحر الشرقي عميق وساحله منتظم نسبيًا (물이 깊고 해안선이 단조롭다).' },
  q394: { q: 'أيّ بحار كوريا يشهد أكبر فرق بين المدّ والجزر وتنتشر فيه المسطحات الطينية الواسعة؟', explain: 'البحر الغربي (서해) ضحل وفرق المدّ والجزر فيه كبير، لذلك تتسع فيه المسطحات الطينية.' },
  q395: { q: 'ما الاسم الإداري الرسمي للعاصمة سيول؟', explain: 'الاسم الرسمي لسيول هو مدينة سيول الخاصة (서울특별시).' },
  q396: { q: 'ما المدينة التي أُنشئت مركزًا إداريًا وانتقلت إليها جهات حكومية مركزية كثيرة؟', explain: 'في مدينة سيجونغ ذات الحكم الذاتي الخاص (세종특별자치시) مجمع حكومي تعمل فيه وزارات كثيرة.' },
  q397: { q: 'ما اسم الوحدة الإدارية للمدن الكبيرة غير التابعة لمقاطعة مثل بوسان وإنتشون؟', explain: 'المدن الكبيرة مثل بوسان وإنتشون مدن حضرية كبرى (광역시) بمستوى المقاطعة.' },
  q398: { q: 'ما الاسم الرسمي المستخدم منذ عام 2024 بدلًا من مقاطعة جولا الشمالية (전라북도)؟', explain: 'أصبحت مقاطعة جولا الشمالية في يناير 2024 مقاطعة جونبوك ذات الحكم الذاتي الخاص (전북특별자치도).' },
  q399: { q: 'ما الاسم الذي يُطلق على سيول وإنتشون ومقاطعة غيونغي معًا؟', explain: 'تُسمّى سيول وإنتشون وغيونغي منطقة العاصمة (수도권)، ويعيش فيها نحو نصف السكان.' },
  q400: { q: 'في أي مدينة يقع أكبر مطار دولي في كوريا؟', explain: 'مطار إنتشون (인천) الدولي هو أكبر مطار دولي في كوريا.' },
}
